`timescale 1ns/1ps

module tb_FP8_NATIVE_MAC_256;

    localparam N       = 256;
    localparam BUS_W   = 2048;
    localparam ACC_W   = 45;
    localparam NUM_VEC = 16; // 11 edge cases + 5 random

    reg clk, rst, valid_in;
    reg  [BUS_W-1:0] fp8_act, fp8_wgt;
    wire done;
    wire signed [ACC_W-1:0] final_acc;

    integer i;
    integer errors;

    reg [BUS_W-1:0] act_vec [0:NUM_VEC-1];
    reg [BUS_W-1:0] wgt_vec [0:NUM_VEC-1];
    reg signed [ACC_W-1:0] exp_vec [0:NUM_VEC-1];
    reg [255:0] test_name [0:NUM_VEC-1]; // enough room for readable ascii names

    FP8_NATIVE_MAC_256 dut (
        .clk(clk),
        .rst(rst),
        .valid_in(valid_in),
        .fp8_act(fp8_act),
        .fp8_wgt(fp8_wgt),
        .done(done),
        .final_acc(final_acc)
    );

    // 100 MHz clock
    always #5 clk = ~clk;

    initial begin
        clk = 0; rst = 1; valid_in = 0;
        fp8_act = 0; fp8_wgt = 0;
        errors = 0;

        test_name[0] = "all_zero";
        act_vec[0]  = 2048';
        wgt_vec[0]  = 2048';
        exp_vec[0]  = 45'sh000000000000;
        test_name[1] = "act_zero_wgt_max";
        act_vec[1]  = 2048';
        wgt_vec[1]  = 2048';
        exp_vec[1]  = 45'sh000000000000;
        test_name[2] = "act_max_wgt_zero";
        act_vec[2]  = 2048';
        wgt_vec[2]  = 2048';
        exp_vec[2]  = 45'sh000000000000;
        test_name[3] = "max_pos_times_max_pos";
        act_vec[3]  = 2048';
        wgt_vec[3]  = 2048';
        exp_vec[3]  = 45'sh0c4000000000;
        test_name[4] = "max_neg_times_max_pos";
        act_vec[4]  = 2048';
        wgt_vec[4]  = 2048';
        exp_vec[4]  = 45'sh13c000000000;
        test_name[5] = "max_neg_times_max_neg";
        act_vec[5]  = 2048';
        wgt_vec[5]  = 2048';
        exp_vec[5]  = 45'sh0c4000000000;
        test_name[6] = "min_normal_sq";
        act_vec[6]  = 2048';
        wgt_vec[6]  = 2048';
        exp_vec[6]  = 45'sh000000004000;
        test_name[7] = "max_subnormal_sq";
        act_vec[7]  = 2048';
        wgt_vec[7]  = 2048';
        exp_vec[7]  = 45'sh000000003100;
        test_name[8] = "min_subnormal_sq";
        act_vec[8]  = 2048';
        wgt_vec[8]  = 2048';
        exp_vec[8]  = 45'sh000000000100;
        test_name[9] = "alternating_sign";
        act_vec[9]  = 2048';
        wgt_vec[9]  = 2048';
        exp_vec[9]  = 45'sh000000000000;
        test_name[10] = "alternating_max_zero";
        act_vec[10]  = 2048';
        wgt_vec[10]  = 2048';
        exp_vec[10]  = 45'sh062000000000;
        test_name[11] = "random_0";
        act_vec[11]  = 2048';
        wgt_vec[11]  = 2048';
        exp_vec[11]  = 45'sh000e4792a258;
        test_name[12] = "random_1";
        act_vec[12]  = 2048';
        wgt_vec[12]  = 2048';
        exp_vec[12]  = 45'sh1feeab24173b;
        test_name[13] = "random_2";
        act_vec[13]  = 2048';
        wgt_vec[13]  = 2048';
        exp_vec[13]  = 45'sh0013a1f1ce86;
        test_name[14] = "random_3";
        act_vec[14]  = 2048';
        wgt_vec[14]  = 2048';
        exp_vec[14]  = 45'sh1fef89b3d7f6;
        test_name[15] = "random_4";
        act_vec[15]  = 2048';
        wgt_vec[15]  = 2048';
        exp_vec[15]  = 45'sh1fef422ea570;

        @(negedge clk); @(negedge clk);
        rst = 0;

        for (i = 0; i < NUM_VEC; i = i + 1) begin
            @(negedge clk);
            fp8_act  = act_vec[i];
            fp8_wgt  = wgt_vec[i];
            valid_in = 1'b1;
            @(negedge clk);
            valid_in = 1'b0;

            @(negedge clk);
            wait (done == 1'b1 || 1); // stage 3 registers same cycle 'done' asserts
            #0.1;

            if (final_acc !== exp_vec[i]) begin
                errors = errors + 1;
                $display("[FAIL] vec %0d (%0s): expected=%0d got=%0d",
                          i, test_name[i], exp_vec[i], final_acc);
            end else begin
                $display("[PASS] vec %0d (%0s): got=%0d", i, test_name[i], final_acc);
            end
        end

        if (errors == 0)
            $display("\n==== ALL %0d TESTS PASSED for FP8_NATIVE_MAC_256 ====", NUM_VEC);
        else
            $display("\n==== %0d / %0d TESTS FAILED for FP8_NATIVE_MAC_256 ====", errors, NUM_VEC);

        $finish;
    end

endmodule
